BEGIN READ ONLY;
SELECT json_build_object('events',count(*),'self_check_in',count(*) FILTER(WHERE e."eventTypeCode"='check_in' AND e."sourceCode"='self_qr' AND e."operatorUserId"=u.id AND e."operatorMemberId"=u."memberId" AND e."memberId"=u."memberId"),'participants',count(distinct e."memberId")) FROM "AttendancePunchEvent" e JOIN "User" u ON u.username='t45-user-b' WHERE e."activityId"=:'target';
SELECT json_build_object('segments',count(*),'open_matching_event',count(*) FILTER(WHERE s."sourceCheckInEventId"=e.id AND s."checkOutAt" IS NULL AND s."statusCode"='draft' AND s."checkInAt"=e."occurredAt")) FROM "ParticipantServiceSegmentRevision" s JOIN "ActivityParticipationIdentity" i ON i.id=s."participationIdentityId" LEFT JOIN "AttendancePunchEvent" e ON e.id=s."sourceCheckInEventId" WHERE i."activityId"=:'target';
SELECT json_build_object('audit_event',a.event,'operation',a.context->'extra'->>'operation','reqId',a.context->>'requestId','success',a.success,'event_link',e.id=a.context->'extra'->>'eventId','actor_link',e."operatorUserId"=a."actorUserId") FROM audit_logs a JOIN "AttendancePunchEvent" e ON e.id=a.context->'extra'->>'eventId' WHERE a."resourceId"=:'target' AND a.context->'extra'->>'operation'='attendance-punch.create';
SELECT json_build_object('cutover_receipts',(select count(*) from "ActivityTimeCutoverReceipt"),'posted_ledger_for_fixture',(select count(*) from "ParticipationLedgerEntry" where "activityId"=:'target'),'closure_for_fixture',(select count(*) from "ActivitySettlementClosureRevision" where "activityId"=:'target'),'pending_corrections',(select count(*) from "CorrectionPendingTimeAllocation"),'evidence_revision',(select "evidenceRevision" from "ActivityEvidenceState" where "activityId"=:'target'));
SELECT json_build_object('nonowner',NOT pg_has_role('srvf_dp_acceptance_runtime',c.relowner,'MEMBER'),'r5_caller_member',pg_has_role('srvf_dp_acceptance_runtime','r5_boundary_caller_h7c6','MEMBER'),'r5_writer_member',pg_has_role('srvf_dp_acceptance_runtime','r5_mat_writer_20261029_q1','MEMBER'),'r5_pending_has_write',has_any_column_privilege('srvf_dp_acceptance_runtime',c.oid,'INSERT,UPDATE') OR has_table_privilege('srvf_dp_acceptance_runtime',c.oid,'DELETE'),'guard_invoker',NOT p.prosecdef) FROM pg_class c CROSS JOIN pg_proc p WHERE c.oid='public."CorrectionPendingTimeAllocation"'::regclass AND p.oid='public.r5_correction_phase_write_guard()'::regprocedure;
ROLLBACK;
